import { Hono } from 'hono'
import { getPrisma } from '../lib/prisma'
import { sign } from 'hono/jwt'
import { env } from 'hono/adapter'
import { compare } from 'bcryptjs'

const app = new Hono()

app.post('/login', async (c) => {
    // Type casting c.env to any for now to avoid specific hono typing errors if any exist.
    const prisma = getPrisma((c.env as any).DATABASE_URL as string)
    try {
        const { employeeId, password } = await c.req.json()

        const user = await prisma.user.findUnique({
            where: { employeeId },
            include: { paidLeaves: false } // Minimal fetch
        })

        if (!user) {
            return c.json({ success: false, message: 'Invalid credentials' }, 401)
        }

        // Use bcrypt to compare the provided password with the hashed password in DB
        const isValidPassword = await compare(password, user.password)
        if (!isValidPassword) {
            return c.json({ success: false, message: 'Invalid credentials' }, 401)
        }

        const { password: _, ...userWithoutPassword } = user
        return c.json({
            success: true,
            user: userWithoutPassword
        })
    } finally {
        // Disconnect immediately to prevent Cloudflare Worker generic 'hung' errors due to open TCP sockets from pg adapter
        await prisma.$disconnect();
    }
})

export default app
